// AUTO-GENERATED by Bloxks — do not edit. Overwritten on every build.
// Drop-in replacement for React Native's Image and ImageBackground (same props,
// same statics). For a REMOTE source ({ uri: 'https://…' }) it shows a soft
// shimmer while the picture downloads, then fades it in; once loaded, the same
// picture shows instantly. Local images (require(...)) render exactly as before.
//   import { Image, ImageBackground } from '../zzz/RemoteImage'
import React, { useEffect, useRef, useState } from 'react'
import {
  Animated,
  Easing,
  Image as RNImage,
  Platform,
  StyleSheet,
  View,
  type ImageBackgroundProps,
  type ImageProps,
  type LayoutChangeEvent,
  type ViewStyle,
} from 'react-native'

const loaded = new Set<string>()
const NATIVE_DRIVER = Platform.OS !== 'web'
const PLACEHOLDER = 'rgba(140,140,150,0.16)'

function remoteUri(source: ImageProps['source']): string | null {
  const first = Array.isArray(source) ? source[0] : source
  const uri = first && typeof first === 'object' ? (first as { uri?: unknown }).uri : null
  return typeof uri === 'string' && /^https?:\/\//i.test(uri) ? uri : null
}

// What the frame carries (size, placement, corners); everything else stays on the picture.
const FRAME_KEYS = new Set([
  'width', 'height', 'minWidth', 'maxWidth', 'minHeight', 'maxHeight',
  'flex', 'flexGrow', 'flexShrink', 'flexBasis', 'alignSelf', 'aspectRatio', 'display',
  'margin', 'marginTop', 'marginBottom', 'marginLeft', 'marginRight',
  'marginHorizontal', 'marginVertical', 'marginStart', 'marginEnd',
  'position', 'top', 'bottom', 'left', 'right', 'start', 'end', 'zIndex',
  'transform', 'opacity', 'elevation',
])
const RADIUS_KEYS = /^border(?:Top|Bottom)?(?:Left|Right|Start|End)?Radius$/

function splitStyle(style: ImageProps['style']) {
  const flat = (StyleSheet.flatten(style) ?? {}) as Record<string, unknown>
  const frame: Record<string, unknown> = { overflow: 'hidden' }
  const image: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(flat)) {
    if (FRAME_KEYS.has(key)) frame[key] = value
    else {
      image[key] = value
      if (RADIUS_KEYS.test(key)) frame[key] = value
    }
  }
  return { frame: frame as ViewStyle, image: { ...image, width: '100%', height: '100%' } as ImageProps['style'] }
}

function Shimmer() {
  const [width, setWidth] = useState(0)
  const x = useRef(new Animated.Value(0)).current
  useEffect(() => {
    if (!width) return
    const loop = Animated.loop(
      Animated.timing(x, { toValue: 1, duration: 1300, easing: Easing.inOut(Easing.ease), useNativeDriver: NATIVE_DRIVER }),
    )
    loop.start()
    return () => loop.stop()
  }, [width, x])
  const band = Math.max(80, width * 0.6)
  const translateX = x.interpolate({ inputRange: [0, 1], outputRange: [-band, width + band] })
  return (
    <View
      pointerEvents="none"
      onLayout={(e: LayoutChangeEvent) => setWidth(e.nativeEvent.layout.width)}
      style={[StyleSheet.absoluteFill, { backgroundColor: PLACEHOLDER }]}
    >
      {width > 0 ? (
        <Animated.View style={{ position: 'absolute', top: 0, bottom: 0, width: band, flexDirection: 'row', transform: [{ translateX }, { skewX: '-12deg' }] }}>
          {[0.03, 0.08, 0.15, 0.24, 0.32, 0.24, 0.15, 0.08, 0.03].map((alpha, i) => (
            <View key={i} style={{ flex: 1, backgroundColor: `rgba(255,255,255,${alpha})` }} />
          ))}
        </Animated.View>
      ) : null}
    </View>
  )
}

const RemoteImage = React.forwardRef<RNImage, ImageProps>(function RemoteImage(props, ref) {
  const uri = remoteUri(props.source)
  const [ready, setReady] = useState(() => !uri || loaded.has(uri))
  const [failed, setFailed] = useState(false)
  const opacity = useRef(new Animated.Value(ready ? 1 : 0)).current
  const mountedAt = useRef(Date.now())

  useEffect(() => {
    const known = !uri || loaded.has(uri)
    mountedAt.current = Date.now()
    setReady(known)
    setFailed(false)
    opacity.setValue(known ? 1 : 0)
  }, [uri, opacity])

  if (!uri) return <RNImage ref={ref} {...props} />

  const { frame, image } = splitStyle(props.style)
  const reveal = () => {
    loaded.add(uri)
    setReady(true)
    // Already cached (preloaded): no fade, the picture is simply there.
    if (Date.now() - mountedAt.current < 60) opacity.setValue(1)
    else Animated.timing(opacity, { toValue: 1, duration: 220, useNativeDriver: NATIVE_DRIVER }).start()
  }
  return (
    <View style={frame}>
      {ready ? null : <Shimmer />}
      {failed ? <View pointerEvents="none" style={[StyleSheet.absoluteFill, { backgroundColor: PLACEHOLDER }]} /> : null}
      <Animated.View style={[StyleSheet.absoluteFill, { opacity }]}>
        <RNImage
          ref={ref}
          {...props}
          style={image}
          onLoad={(e) => {
            reveal()
            props.onLoad?.(e)
          }}
          onError={(e) => {
            setReady(true)
            setFailed(true)
            props.onError?.(e)
          }}
        />
      </Animated.View>
    </View>
  )
})

type ImageComponent = typeof RemoteImage & {
  prefetch: typeof RNImage.prefetch
  getSize: typeof RNImage.getSize
  getSizeWithHeaders: typeof RNImage.getSizeWithHeaders
  queryCache: typeof RNImage.queryCache
  resolveAssetSource: typeof RNImage.resolveAssetSource
  abortPrefetch: typeof RNImage.abortPrefetch
}

export const Image = Object.assign(RemoteImage, {
  prefetch: RNImage.prefetch,
  getSize: RNImage.getSize,
  getSizeWithHeaders: RNImage.getSizeWithHeaders,
  queryCache: RNImage.queryCache,
  resolveAssetSource: RNImage.resolveAssetSource,
  abortPrefetch: RNImage.abortPrefetch,
}) as ImageComponent

/** Same contract as React Native's ImageBackground, with the shimmer while it loads. */
export function ImageBackground({ children, style, imageStyle, imageRef, ...props }: ImageBackgroundProps) {
  const flat = (StyleSheet.flatten(style) ?? {}) as ViewStyle
  return (
    <View style={style} accessibilityIgnoresInvertColors>
      <Image
        {...props}
        ref={imageRef as never}
        style={[StyleSheet.absoluteFill, { width: flat.width, height: flat.height }, imageStyle]}
      />
      {children}
    </View>
  )
}

/** Downloads pictures ahead of time (next onboarding pages, a list's first items). */
export function preloadImages(sources: ReadonlyArray<ImageProps['source']>): void {
  for (const source of sources) {
    const uri = remoteUri(source)
    if (!uri || loaded.has(uri) || typeof RNImage.prefetch !== 'function') continue
    Promise.resolve(RNImage.prefetch(uri)).then(() => { loaded.add(uri) }, () => {})
  }
}
